from lib import *
S = SS('f183')
R = J('f183'); b = R['basic']; bo = b['boom'][1]; P = R['pii']; SD = R['send']; LA = R['lat']; EX = R['exit']
kl = list(LA)
steps = [
    step(f"用 sentry-sdk 2.71.0 的 FlaskIntegration,配一个自写的 Transport(只把事件收进列表,不联网)来看会上报什么。视图里未处理的 1/0 → HTTP {b['boom'][0]},上报 1 个事件:{bo['type']}: {bo['value']},带 {bo['frames']} 帧调用栈、最内层 {bo['top']}、请求 {bo['method']} {bo['url']}、transaction={bo['transaction']}。abort(404) → 上报 {b['404'][1]} 个(HTTP 异常不当作错误);视图里自己 try/except 后调用 capture_exception → 上报 {b['handled'][1]} 个(mechanism={b['handled'][2]});注册了 @errorhandler(Exception) 返回 JSON 时,同样的 /boom → HTTP {b['errorhandler'][0]},上报 {b['errorhandler'][1]} 个——被自己的 errorhandler 接住的异常,Sentry 默认看不到。要么在 handler 里手动 capture_exception,要么别用兜底 handler 吞掉它。", t=tl(S(1)), done=lidx(S(1), '未处理的', '自己 capture'), mark=lidx(S(1), 'abort(404)', 'errorhandler'), kv=KV([['未处理异常', '上报,带栈与请求'], ['404', '不上报'], ['@errorhandler(Exception)', '不上报(0 个)']], ['@errorhandler(Exception)'])),
    step(f"请求里的敏感信息:发一个带 Cookie、Authorization 头、?token= 查询参数、JSON 里有 password 的 POST,让视图抛异常。默认(send_default_pii=False):Authorization 与 Cookie 头显示 {P['False']['headers']['Authorization']},JSON 里的 password 是 {P['False']['data']['password']},cookies 不带;但查询字符串 {P['False']['query']} 原样在事件里,异常消息里自己写进去的用户名({P['False']['msg']!r})也原样在。send_default_pii=True 后多了 cookies(值仍是 [Filtered])和 user.ip_address。SDK 默认过滤的是常见字段名,不认识的 query 参数和你自己拼进异常消息的内容不会被过滤;别把敏感值放进 URL 或异常文本。", t=tl(S(2)), done=lidx(S(2), 'send_default_pii=False'), mark=lidx(S(2), 'send_default_pii=True'), kv=KV([['Authorization / Cookie / password', '[Filtered]'], ['?token=', '原样上报'], ['异常消息里的用户名', '原样上报']], ['?token='])),
    step(f"上报前过滤和采样:before_send 函数返回 None 就丢弃事件——丢掉 ZeroDivisionError 后,/boom 与 /login 两次请求的事件里只剩 {SD['before_send']}。sample_rate=0.5 时 400 次异常上报了 {SD['sample']} 个(这是随机的:这一次的结果;同一段另外跑 3 次是 204、199、227)。错误洪水时用采样和过滤控制量,但被采样掉的错误是真的丢了。", t=tl(S(3)), done=lidx(S(3), 'before_send'), mark=lidx(S(3), 'sample_rate'), kv=KV([['before_send', '返回 None 丢弃'], ['sample_rate=0.5', f"400 → {SD['sample']}"]], ['sample_rate=0.5'])),
    step(f"收集端不可达或卡住时,SDK 对应用的影响(真实 transport,DSN 指向本机端口):/boom 请求中位耗时——没初始化 sentry {LA[kl[0]]:.1f} ms,DSN 端口无人监听 {LA[kl[1]]:.1f} ms,端口接受连接但不回复 {LA[kl[2]]:.1f} ms:发送在后台线程里,请求本身没有被拖慢。但 SIGTERM 后进程退出的时间:{EX[kl[0]]:.2f} s、{EX[kl[1]]:.2f} s、{EX[kl[2]]:.2f} s——收集端卡住时,退出会在 flush 里多等约 2 秒(SDK 的 shutdown_timeout 默认 2 秒),这些事件最终还是发不出去。滚动发布的优雅关闭时间要把这 2 秒算进去。", t=tl(S(4)), done=lidx(S(4), '没有初始化', '无人监听'), mark=lidx(S(4), '接受连接但不回复'), b=bars([[k, EX[k], f'{EX[k]:.2f} s'] for k in kl], 2.6, mark=[2], done=[0, 1]), kv=KV([['请求耗时', '没有被拖慢(后台线程发送)'], ['退出', f"卡住的收集端多等 {EX[kl[2]] - EX[kl[0]]:.1f} s"]], ['退出'])),
]
A = mkartf('f183', 183, 'Flask,Sentry,错误监控,sentry-sdk,真实验证,动画演示',
    f'用真实的 sentry-sdk 2.71.0(自写 Transport 收事件)验证 Flask 错误监控:未处理异常上报、abort(404) 与被 @errorhandler(Exception) 接住的异常不上报、Authorization/Cookie/password 被过滤但 ?token= 与异常消息里的内容不过滤、before_send 与 sample_rate、收集端卡住时请求不变慢但进程退出多等约 {EX[kl[2]] - EX[kl[0]]:.1f} 秒。',
    '线上的异常要靠监控发现。用 Sentry 之类的服务时有几件事要先弄清楚:哪些异常会被上报、请求里的哪些敏感数据会被带上、收集端出问题时会不会拖慢应用。这篇用真实的 sentry-sdk 配自写的 transport 逐项验证,没有联网、没有用真实的 Sentry 服务(日志与请求 ID 见第 181、182 篇)。',
    [('0 个', '被自己的 @errorhandler(Exception) 接住的异常上报的事件数'), ('?token=', '查询字符串里的参数没有被默认过滤'), (f'+{EX[kl[2]] - EX[kl[0]]:.1f} s', '收集端卡住时 SIGTERM 后进程退出多等的时间')],
    [('上报哪些异常', '<p>上一篇:<a href="flask-request-id-tracing.html">请求 ID 链路追踪</a>;下一篇:<a href="flask-env-injection.html">环境变量注入</a>。</p><p>只用本机进程和自写 Transport,没有连接任何 Sentry 服务。</p>'), ('敏感信息', None), ('过滤与采样', None), ('收集端不可用', None)],
    steps, [ENV_F + '。sentry-sdk 2.71.0(FlaskIntegration、自写 Transport),gunicorn', '没有验证:真实的 Sentry 服务端(事件分组、告警、面包屑在界面里的样子)、性能追踪(traces_sample_rate)、release 与 source map、其它监控产品、在多 worker 下按进程初始化的差别(这里只用 1 个 worker)'], 'Flask 错误监控')
